arguments.command:
cd /app/documents; cat > /tmp/f.py <<'EOF'
import sys, pypdf
for p in sys.argv[1:]:
    r=pypdf.PdfReader(p)
    f=r.get_fields() or {}
    print("===",p, len(f))
    for k,v in f.items():
        val=v.get('/V')
        if val not in (None,'','/Off'): print(' ',k,'=',val)
EOF
for y in 2023 2024 2025; do python3 -I /tmp/f.py $y/w2.pdf $y/1099-int.pdf $y/1099-b_1.pdf $y/1099-b_2.pdf; done

